<?php require_once __DIR__.'/../includes/auth.php';require_admin();$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM articles WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$title=trim($_POST['title']);$slug=slugify($_POST['slug']?:$title);$excerpt=trim($_POST['excerpt']);$content=$_POST['content_html'];$cat=(int)$_POST['category_id'];$status=$_POST['status']==='published'?'published':'draft';if($id){$s=$pdo->prepare('UPDATE articles SET category_id=?,title=?,slug=?,excerpt=?,content_html=?,status=?,published_at=IF(?=\'published\',COALESCE(published_at,NOW()),published_at),updated_at=NOW() WHERE id=?');$s->execute([$cat,$title,$slug,$excerpt,$content,$status,$status,$id]);}else{$s=$pdo->prepare('INSERT INTO articles(category_id,title,slug,excerpt,content_html,status,published_at) VALUES(?,?,?,?,?,?,IF(?=\'published\',NOW(),NULL))');$s->execute([$cat,$title,$slug,$excerpt,$content,$status,$status]);}redirect_to('admin/articles.php');}$rows=$pdo->query('SELECT a.*,c.name category_name FROM articles a JOIN categories c ON c.id=a.category_id ORDER BY a.id DESC')->fetchAll();$page_title='Articles';require __DIR__.'/../includes/header.php';?><section class="section-head"><h1>Articles</h1></section><div class="card"><div class="card-body"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=e((string)($edit['id']??0))?>"><p><input name="title" placeholder="Title" required value="<?=e($edit['title']??'')?>"></p><p><input name="slug" placeholder="Slug (optional)" value="<?=e($edit['slug']??'')?>"></p><p><select name="category_id"><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($edit['category_id']??0)==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></p><p><input name="excerpt" placeholder="Short excerpt" required value="<?=e($edit['excerpt']??'')?>"></p><p><textarea name="content_html" rows="12" placeholder="HTML content" required><?=e($edit['content_html']??'')?></textarea></p><p><select name="status"><option value="draft">Draft</option><option value="published" <?=($edit['status']??'')==='published'?'selected':''?>>Published</option></select></p><button class="btn">Save Article</button></form></div></div><div class="results"><?php foreach($rows as $r):?><article class="result"><b><?=e($r['title'])?></b> — <?=e($r['category_name'])?> — <?=e($r['status'])?> <a href="?edit=<?=$r['id']?>">Edit</a></article><?php endforeach;?></div><?php require __DIR__.'/../includes/footer.php';?>
